#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>

int main() {
    const char* results = "Sample results content.";
    char* filename = (char*)malloc(1024 * sizeof(char));
    if (filename == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    // Generate a unique filename with a timestamp
    snprintf(filename, 1024, "/tmp/results_%d.txt", (int)time(NULL));

    // Open the file with exclusive creation and write permissions
    int fd = open(filename, O_CREAT | O_WRONLY | O_EXCL, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        fprintf(stderr, "Failed to create file: %s\n", strerror(errno));
        free(filename);
        return 1;
    }

    // Write results to the file
    ssize_t bytes_written = write(fd, results, strlen(results));
    if (bytes_written == -1) {
        fprintf(stderr, "Failed to write to file: %s\n", strerror(errno));
        close(fd);
        free(filename);
        return 1;
    }

    // Close the file and return the filename
    close(fd);
    printf("File created successfully: %s\n", filename);
    free(filename);
    return 0;
}
